const data = $input.first().json;

const emaCurrent = data.ema_current_status || 'UNKNOWN';
const emaPrev = data.ema_prev_status || 'UNKNOWN';
const emaCurrentSeconds = data.ema_current_seconds ?? 999999;
const emaPrevSeconds = data.ema_prev_seconds ?? 0;

const actCurrent = data.act_current_status || 'UNKNOWN';
const actCurrentSeconds = data.act_current_seconds ?? 0;

let alertType = 'NONE';
let message = '';

// 1. CASO CAÍDA PROLONGADA (Batería Agotada o Apagón):
// El nodo EMA debe llevar en OFFLINE continuo exactamente entre 5 y 6 minutos (300 a 360 segundos).
// Tras el timeout del watchdog, se dispara EXACTAMENTE UNA VEZ.
if (emaCurrent === 'OFFLINE' && emaCurrentSeconds >= 300 && emaCurrentSeconds < 360) {
  if (actCurrent === 'OFFLINE' && actCurrentSeconds >= 300) {
    alertType = 'SIN_CONEXION_WIFI';
    message = '\u200B\n*Sin Conexión WiFi*\n\n*Nodo EMA:* OFFLINE\n*Nodo Actuador:* OFFLINE';
  } else {
    alertType = 'BATERIA_AGOTADA';
    message = '\u200B\n*Bateria Agotada*\n\n*Nodo EMA:* OFFLINE';
  }
}
// 2. CASO RESTABLECIMIENTO:
// El nodo EMA acaba de conectarse ONLINE (en los primeros 60 segundos del cambio),
// habiendo venido de un OFFLINE REAL que duró al menos 10 minutos (>= 600 segundos).
// NOTA: SLEEP es estado rutinario de reposo, nunca dispara restablecimiento.
else if (
  emaCurrent === 'ONLINE' &&
  emaPrev === 'OFFLINE' &&
  emaCurrentSeconds >= 0 &&
  emaCurrentSeconds < 60 &&
  emaPrevSeconds >= 600
) {
  alertType = 'EMA_RESTABLECIDO';
  message = '\u200B\n*Nodo EMA* Operativo.';
}

if (alertType === 'NONE') {
  return [];
}

return [{ json: { alertType, message } }];
